namespace OpenFatoAI.Domain.Entities;

/// <summary>
/// A saved session (Home quick action or transcription). Mirrors the desktop app's local
/// SQLite table; scoped by the anonymous InstallationId generated by each app install.
/// </summary>
public class Meeting
{
    public Guid           Id              { get; set; }
    public Guid           InstallationId  { get; set; }
    public string         SessionHash     { get; set; } = "";
    public short          MeetingType     { get; set; } = 1;   // 1 = Home, 2 = Transcriptions
    public string?        SummaryType     { get; set; }
    public string?        TranscriptText  { get; set; }
    public string?        AiSummary       { get; set; }
    public string?        PromptUsed      { get; set; }
    public int            RecordedSeconds { get; set; }
    public string?        AiProvider      { get; set; }
    public string?        AiModel         { get; set; }
    public string?        Language        { get; set; }
    public DateTimeOffset CreatedAt       { get; set; }
    public DateTimeOffset UpdatedAt       { get; set; }
}
